// client/src/components/LoginModal.jsx
import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

/**
 * LoginModal.jsx
 * - Works with your server endpoints:
 *     POST /api/auth/otp/request  -> { ok, demo?, otp? }
 *     POST /api/auth/otp/verify   -> { ok, token, user }
 *
 * Props:
 * - open: boolean
 * - onClose: function
 * - onLogin: function(response)  // called with server response on success
 */

export default function LoginModal({ open, onClose, onLogin }) {
  const [step, setStep] = useState(0); // 0 = phone entry, 1 = OTP verify
  const [phone, setPhone] = useState("");
  const [name, setName] = useState("");
  const [otp, setOtp] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [demoOtp, setDemoOtp] = useState(null);

  useEffect(() => {
    if (!open) {
      // reset when closed
      setStep(0);
      setPhone("");
      setName("");
      setOtp("");
      setDemoOtp(null);
      setMessage("");
      setLoading(false);
    }
  }, [open]);

  async function requestOtp(e) {
    e && e.preventDefault();
    setMessage("");
    if (!phone) {
      setMessage("Enter your phone number (with country code, e.g. +91...)");
      return;
    }

    setLoading(true);
    try {
      const res = await fetch("/api/auth/otp/request", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone }),
      });
      const data = await res.json();
      setLoading(false);

      if (data?.ok) {
        setStep(1);
        setMessage("OTP sent — check your phone.");
        if (data.demo && data.otp) {
          // server can optionally return demo OTP for local/testing
          setDemoOtp(data.otp);
        }
        // focus OTP input after a brief delay
        setTimeout(() => document.getElementById("otpInput")?.focus(), 180);
      } else {
        setMessage(data?.error || "Failed to send OTP. Check server logs.");
      }
    } catch (err) {
      setLoading(false);
      console.error(err);
      setMessage("Network error while requesting OTP.");
    }
  }

  async function verifyOtp(e) {
    e && e.preventDefault();
    setMessage("");
    if (!otp) {
      setMessage("Please enter the OTP you received.");
      return;
    }

    setLoading(true);
    try {
      const res = await fetch("/api/auth/otp/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone, otp, name }),
      });
      const data = await res.json();
      setLoading(false);

      if (data?.ok) {
        setMessage("Login successful!");
        if (typeof onLogin === "function") onLogin(data);
        // small delay to show success then close
        setTimeout(() => {
          onClose();
        }, 600);
      } else {
        setMessage(data?.error || "OTP verification failed.");
      }
    } catch (err) {
      setLoading(false);
      console.error(err);
      setMessage("Network error while verifying OTP.");
    }
  }

  if (!open) return null;

  return (
    <AnimatePresence>
      <motion.div
        key="backdrop"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        style={{
          position: "fixed",
          inset: 0,
          background: "rgba(15,18,25,0.55)",
          zIndex: 9998,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: 16,
        }}
        onClick={onClose}
      >
        <motion.div
          key="modal"
          initial={{ y: 30, opacity: 0, scale: 0.98 }}
          animate={{ y: 0, opacity: 1, scale: 1 }}
          exit={{ y: 30, opacity: 0, scale: 0.98 }}
          transition={{ duration: 0.22 }}
          onClick={(e) => e.stopPropagation()}
          style={{
            width: 440,
            maxWidth: "96%",
            background: "white",
            borderRadius: 14,
            padding: 20,
            boxShadow: "0 25px 60px rgba(2,6,23,0.32)",
          }}
        >
          {/* Header */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div>
              <h3 style={{ margin: 0 }}>Sign in / Register</h3>
              <div style={{ color: "#6b7280", fontSize: 13, marginTop: 6 }}>
                Enter your mobile number to receive a one-time code
              </div>
            </div>

            <div>
              <button
                onClick={onClose}
                aria-label="Close"
                style={{
                  background: "transparent",
                  border: 0,
                  fontSize: 20,
                  cursor: "pointer",
                  color: "#6b7280",
                }}
              >
                ✕
              </button>
            </div>
          </div>

          <div style={{ height: 12 }} />

          {/* Step 0: phone entry */}
          {step === 0 && (
            <form onSubmit={requestOtp} style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <input
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder="+91 98xxxxxxxx"
                style={{
                  padding: 12,
                  fontSize: 15,
                  borderRadius: 10,
                  border: "1px solid #eef3ff",
                }}
              />

              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Your name (optional)"
                style={{
                  padding: 12,
                  fontSize: 15,
                  borderRadius: 10,
                  border: "1px solid #eef3ff",
                }}
              />

              <div style={{ display: "flex", gap: 10, marginTop: 6 }}>
                <button
                  type="submit"
                  className="btn"
                  style={{ flex: 1 }}
                  disabled={loading}
                >
                  {loading ? "Sending..." : "Send OTP"}
                </button>

                <button
                  type="button"
                  className="btn btn-outline"
                  style={{ flex: 1 }}
                  onClick={() => alert("Google Sign-in can be added later via Firebase / OAuth.")}
                >
                  Google
                </button>
              </div>

              <div style={{ color: "#6b7280", fontSize: 13 }}>
                For demo — if Twilio is disabled the server may return a demo OTP (shown below).
              </div>

              {demoOtp && (
                <div
                  style={{
                    marginTop: 8,
                    padding: 10,
                    borderRadius: 8,
                    background: "#f8fafc",
                    border: "1px dashed #cbd5e1",
                    fontSize: 14,
                  }}
                >
                  Demo OTP: <strong>{demoOtp}</strong>
                </div>
              )}
            </form>
          )}

          {/* Step 1: verify OTP */}
          {step === 1 && (
            <form onSubmit={verifyOtp} style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <input
                id="otpInput"
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                placeholder="Enter 6-digit OTP"
                style={{
                  padding: 12,
                  fontSize: 15,
                  borderRadius: 10,
                  border: "1px solid #eef3ff",
                }}
              />

              <div style={{ display: "flex", gap: 10 }}>
                <button
                  type="submit"
                  className="btn"
                  style={{ flex: 1 }}
                  disabled={loading}
                >
                  {loading ? "Verifying..." : "Verify OTP"}
                </button>

                <button
                  type="button"
                  className="btn btn-outline"
                  style={{ flex: 1 }}
                  onClick={() => {
                    setStep(0);
                    setOtp("");
                    setDemoOtp(null);
                    setMessage("");
                  }}
                >
                  Back
                </button>
              </div>

              <div style={{ color: "#6b7280", fontSize: 13 }}>
                Didn’t get the code? Try resend or check the server terminal for demo OTP.
              </div>
            </form>
          )}

          {/* Message area */}
          {message && (
            <div style={{ marginTop: 10, color: "#374151", fontSize: 14 }}>{message}</div>
          )}

          <div style={{ marginTop: 12, display: "flex", gap: 8 }}>
            <button
              className="btn-outline"
              onClick={() => {
                setStep(0);
                setPhone("");
                setName("");
                setOtp("");
                setDemoOtp(null);
                setMessage("");
              }}
              style={{ flex: 1 }}
            >
              Reset
            </button>

            <button
              className="btn-outline"
              onClick={onClose}
              style={{ flex: 1 }}
            >
              Close
            </button>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
